    let skip_inv_update = schar((((oflgs & NHM.ONAME_SKIP_INVUPD) >>> 0) != 0));

    lth = cptr.ld1s(name)
            ? Number(BigInt.asIntN(32, (BigInt.asUintN(64, cptr.strlen(name) + 1n))))
            : 0;
