        /* can't dual-wield with artifact as secondary weapon */
        if (cptr.eq(obj, uswapwep.v))
            untwoweapon();
        /* activate warning if you've just named your weapon "Sting" */
        if (cptr.eq(obj, uwep.v))
            set_artifact_intrinsic(obj, 1, 256n);
