        if (!strncmpi((lookname), (cptr.ldPtro(sir_Terry_novels, k, 8)), -1) ||
                !strncmpi((The(lookname)), (cptr.ldPtro(sir_Terry_novels, k, 8)), -1)) {
            if (idx)
                cptr.stI32(idx, k);
            return cptr.ldPtro(sir_Terry_novels, k, 8);
        }
